<?php
declare(strict_types=1);
require_once __DIR__.'/academic.php';
require_once __DIR__.'/certificates.php';
const TERM_CONSENT_VERSION=2;
const TERM_CAPACITY=6;
const TERM_RUBRIC=['originality','reasoning','structure','evidence','apa'];
function term_courses():array{
 static $courses;if($courses!==null)return $courses;
 $courses=json_decode(file_get_contents(__DIR__.'/term-courses.json'),true,128,JSON_THROW_ON_ERROR);
 return $courses;
}
function term_course(string $id):array{$courses=term_courses();demand(isset($courses[$id]),'Choose an available course.');return $courses[$id];}
function terms_ready():bool{try{query('SELECT id FROM term_scheduler LIMIT 1');query('SELECT paper_id FROM term_peer_routes LIMIT 1');return true;}catch(PDOException $e){if(preg_match('/no such table|doesn.t exist/i',$e->getMessage()))return false;throw $e;}}
function terms_install():void{
 demand(academic_ready(),'Enable College Success and academic writing first.');
 demand(count(term_courses())===4,'Prepare all four standard courses before enabling enrollment.');
 foreach(term_courses() as $course){demand(count($course['weeks'])===10,'Each standard course needs ten teaching weeks.');foreach($course['weeks'] as $w)demand(count($w['questions'])===10,'Complete every module checkpoint.');demand(count($course['final']['a'])===15&&count($course['final']['b'])===10,'Complete each final examination.');}
 $sql=file_get_contents(dirname(__DIR__).'/database/course-terms.sql');
 if(db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite')$sql=str_replace(' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci','',$sql);
 else{$c=query("SELECT COLLATION_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='users' AND COLUMN_NAME='id'")->fetchColumn();demand(is_string($c)&&preg_match('/^utf8mb4_[a-zA-Z0-9_]+$/D',$c),'Check the account database encoding.');$sql=str_replace('utf8mb4_unicode_ci',$c,$sql);}
 foreach(explode(';',$sql) as $q)if(trim($q)!=='')db()->exec($q);
}
function term_zone():DateTimeZone{return new DateTimeZone('Africa/Nairobi');}
function term_next_monday(int $now):string{return (new DateTimeImmutable('@'.$now))->setTimezone(term_zone())->modify('next monday')->setTime(0,0)->format('Y-m-d');}
function term_intake_date(int $now):string{return (new DateTimeImmutable('@'.$now))->setTimezone(term_zone())->modify('monday this week')->setTime(0,0)->format('Y-m-d');}
function term_study_clock(array $enrollment,int $now):array{$start=strtotime($enrollment['enrolled_at']);return ['start'=>$start,'end'=>$start+84*86400,'weekIndex'=>max(0,(int)floor(($now-$start)/604800)),'startDate'=>(new DateTimeImmutable('@'.$start))->setTimezone(term_zone())->format('Y-m-d'),'endDate'=>(new DateTimeImmutable('@'.($start+84*86400)))->setTimezone(term_zone())->format('Y-m-d'),'zone'=>'Africa/Nairobi','recommendedOnly'=>true];}
function term_service_cutoff(int $now):int{$date=(new DateTimeImmutable('@'.$now))->setTimezone(term_zone())->modify('thursday this week')->setTime(8,0);if($date->getTimestamp()>$now)$date=$date->modify('-7 days');return $date->getTimestamp();}
function term_next_service(int $now):int{return term_service_cutoff($now)+7*86400;}
function term_lock_enrollment(string $id):void{if(db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql')query('SELECT id FROM term_enrollments WHERE id=? FOR UPDATE',[$id])->fetch();else query('UPDATE term_enrollments SET id=id WHERE id=?',[$id]);}
function term_lock_offering(string $id):void{if(db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql')query('SELECT id FROM term_offerings WHERE id=? FOR UPDATE',[$id])->fetch();else query('UPDATE term_offerings SET id=id WHERE id=?',[$id]);}
function term_start(array $offering):DateTimeImmutable{$date=DateTimeImmutable::createFromFormat('!Y-m-d',$offering['start_date'],term_zone());if(!$date||$date->format('Y-m-d')!==$offering['start_date']||$date->format('N')!=='1')throw new RuntimeException('Invalid course start date.');return $date;}
function term_clock(array $offering,int $now):array{$start=term_start($offering);$end=$start->modify('+84 days');return ['start'=>$start->getTimestamp(),'end'=>$end->getTimestamp(),'weekIndex'=>(int)floor(($now-$start->getTimestamp())/604800),'startDate'=>$start->format('Y-m-d'),'endDate'=>$end->modify('-1 day')->format('Y-m-d'),'zone'=>'Africa/Nairobi'];}
function term_cutoff(array $offering,int $week):int{demand($week>=0&&$week<10,'Choose a teaching week.');return term_start($offering)->modify('+'.($week*7+3).' days')->setTime(8,0)->getTimestamp();}
function term_offering(string $id):array{demand((bool)preg_match('/^[a-f0-9]{8}$/D',$id),'Choose a valid class.');$row=query('SELECT * FROM term_offerings WHERE id=?',[$id])->fetch();demand((bool)$row,'This class was not found.');return $row;}
function term_professor(?array $u,string $offering):bool{return $u&&$u['verified_at']!==null&&(campus_staff($u)||(bool)query('SELECT 1 FROM term_professors WHERE offering_id=? AND user_id=?',[$offering,$u['id']])->fetchColumn());}
function term_enrollment(array $u,string $offering):array{$r=query('SELECT * FROM term_enrollments WHERE offering_id=? AND user_id=?',[$offering,$u['id']])->fetch();demand((bool)$r,'Enroll in this class to save its work.');return $r;}
function term_touch(string $id,int $now):void{query('UPDATE term_enrollments SET last_activity_at=? WHERE id=?',[gmdate('c',$now),$id]);}
function term_latest(string $enrollment,int $week,string $task):?array{return query('SELECT * FROM term_papers WHERE enrollment_id=? AND week_index=? AND task_kind=? ORDER BY revision DESC LIMIT 1',[$enrollment,$week,$task])->fetch()?:null;}
function term_latest_submitted(string $enrollment,int $week,string $task):?array{return query("SELECT * FROM term_papers WHERE enrollment_id=? AND week_index=? AND task_kind=? AND status='submitted' ORDER BY revision DESC LIMIT 1",[$enrollment,$week,$task])->fetch()?:null;}
function term_public_paper(?array $p):?array{if(!$p)return null;return ['allocated'=>(bool)query('SELECT 1 FROM term_peer_assignments WHERE paper_id=?',[$p['id']])->fetchColumn(),'id'=>$p['id'],'week'=>(int)$p['week_index'],'task'=>$p['task_kind'],'revision'=>(int)$p['revision'],'version'=>(int)$p['version'],'document'=>json_decode($p['document_json'],true),'words'=>(int)$p['word_count'],'status'=>$p['status'],'teacherStatus'=>$p['teacher_status'],'feedback'=>$p['feedback'],'rubric'=>$p['rubric_json']?json_decode($p['rubric_json'],true):null,'submittedAt'=>$p['submitted_at'],'reviewedAt'=>$p['reviewed_at'],'peerRoute'=>term_peer_route($p['id'])];}
function term_enroll(array $u,string $course,int $now,array $body):array{
 term_course($course);demand($u['verified_at']!==null,'Verify your account before enrolling.');demand(college_complete($u['id']),'Complete the short College Success foundation before enrolling in a standard course.');demand(($body['consentVersion']??0)===TERM_CONSENT_VERSION&&($body['peerConsent']??false)===true,'Read and agree to self-paced study, peer-review sharing and integrity rules.');
 $start=term_intake_date($now);$mysql=db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql';
 // Find a possible current enrollment before opening the transaction, so a
 // repeatable-read snapshot cannot predate the intake capacity lock.
 $active=query("SELECT e.id,e.offering_id FROM term_enrollments e JOIN term_offerings o ON o.id=e.offering_id WHERE e.user_id=? AND o.course_id=? AND e.status IN ('enrolled','finished') ORDER BY e.enrolled_at DESC LIMIT 1",[$u['id'],$course])->fetch();
 db()->beginTransaction();try{
  if(!$mysql)query('UPDATE term_offerings SET id=id WHERE course_id=? AND start_date=?',[$course,$start]);
  if($active){term_lock_offering($active['offering_id']);term_lock_enrollment($active['id']);$existing=query('SELECT * FROM term_enrollments WHERE id=?'.($mysql?' FOR UPDATE':''),[$active['id']])->fetch();if($existing&&in_array($existing['status'],['enrolled','finished'],true)){$off=term_offering($active['offering_id']);db()->commit();return ['offering'=>$off,'enrollment'=>$existing,'notice'=>'Your current enrollment is already saved. You can study at your own pace.'];}}
  $off=query('SELECT * FROM term_offerings WHERE course_id=? AND start_date=?'.($mysql?' FOR UPDATE':''),[$course,$start])->fetch();
  if(!$off){$id=bin2hex(random_bytes(4));try{query('INSERT INTO term_offerings (id,course_id,start_date,created_at) VALUES (?,?,?,?)',[$id,$course,$start,gmdate('c',$now)]);}catch(PDOException $e){if(!in_array((string)$e->getCode(),['23000','23505'],true))throw $e;}$off=query('SELECT * FROM term_offerings WHERE course_id=? AND start_date=?'.($mysql?' FOR UPDATE':''),[$course,$start])->fetch();}
  if(!$off)throw new RuntimeException('Class enrollment conflicted.');$existing=query('SELECT * FROM term_enrollments WHERE offering_id=? AND user_id=?',[$off['id'],$u['id']])->fetch();if($existing){db()->commit();return ['offering'=>$off,'enrollment'=>$existing,'notice'=>'Your enrollment is already saved.'];}
  $count=(int)query('SELECT COUNT(*) FROM term_enrollments WHERE offering_id=?',[$off['id']])->fetchColumn();demand($count<TERM_CAPACITY,'This intake group has reached its six-student limit. Enrollment is closed for this administrative intake week.');
  $id=bin2hex(random_bytes(16));query('INSERT INTO term_enrollments (id,offering_id,user_id,status,consent_version,enrolled_at) VALUES (?,?,?,?,?,?)',[$id,$off['id'],$u['id'],'enrolled',TERM_CONSENT_VERSION,gmdate('c',$now)]);campus_audit($u,'term_enroll',$id,['course'=>$course,'start'=>$start,'capacity'=>TERM_CAPACITY]);db()->commit();return ['offering'=>$off,'enrollment'=>query('SELECT * FROM term_enrollments WHERE id=?',[$id])->fetch(),'notice'=>'Enrollment saved. Your materials are available now. The intake date identifies your administrative group; it does not delay study.'];
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function term_assessment_key(string $offering,string $part):string{demand((bool)preg_match('/^(w(?:0[1-9]|10)|m|f)$/D',$part),'Choose a course assessment.');return 't-'.$offering.'-'.$part;}
function term_passed(string $userId,string $offering,string $part):bool{return (bool)query('SELECT 1 FROM assessment_attempts WHERE user_id=? AND assessment_key=? AND passed=1 AND submitted_at IS NOT NULL LIMIT 1',[$userId,term_assessment_key($offering,$part)])->fetchColumn();}
function term_previous_passed(array $enrollment,int $week):bool{for($i=0;$i<$week;$i++)if(!term_passed($enrollment['user_id'],$enrollment['offering_id'],'w'.sprintf('%02d',$i+1)))return false;return $week<6||term_passed($enrollment['user_id'],$enrollment['offering_id'],'m');}
function term_deadline(array $enrollment,array $offering,int $week):array{$normal=term_cutoff($offering,$week);$extension=query('SELECT until_at,reason FROM term_extensions WHERE enrollment_id=? AND week_index=?',[$enrollment['id'],$week])->fetch();$extra=$extension?strtotime($extension['until_at']):0;return ['normal'=>$normal,'effective'=>max($normal,$extra),'extension'=>$extra>$normal?$extension:null];}
function term_writing_available(array $enrollment,array $offering,int $week,int $now):bool{demand($week>=0&&$week<10,'Choose a teaching module.');return in_array($enrollment['status'],['enrolled','finished','completed'],true)&&term_previous_passed($enrollment,$week);}

function term_save_paper(array $u,array $body,int $now,bool $submit):array{
 $off=term_offering((string)($body['offering']??''));$en=term_enrollment($u,$off['id']);$week=$body['week']??null;$task=$body['task']??'';demand(is_int($week)&&$week>=0&&$week<10&&in_array($task,['opening','closing'],true),'Choose a valid module writing task.');demand(term_writing_available($en,$off,$week,$now),'Pass the preceding module requirements before submitting assessed writing. Reading and private practice remain available.');
 if($task==='closing')demand((term_latest_submitted($en['id'],$week,'opening')['submitted_at']??null)!==null,'Submit your opening discussion before the closing response.');$validated=academic_document($body['document']??null,$task,$submit);demand(is_int($body['version']??null),'Refresh your saved paper.');if($submit)demand(($body['original']??false)===true&&($body['peerConsent']??false)===true&&($body['consentVersion']??0)===TERM_CONSENT_VERSION,'Confirm your authorship and the peer-review sharing rules.');
 db()->beginTransaction();try{term_lock_offering($off['id']);term_lock_enrollment($en['id']);$en=query('SELECT * FROM term_enrollments WHERE id=?',[$en['id']])->fetch();demand(term_writing_available($en,$off,$week,$now),'This enrollment cannot submit assessed work.');$old=term_latest($en['id'],$week,$task);if((int)($old['version']??0)!==$body['version']){db()->rollBack();reply(['error'=>'This paper changed on another device. Compare the saved version before replacing it.','conflict'=>true],409);}
  demand((term_latest_submitted($en['id'],$week,$task)['teacher_status']??'')!=='accepted','Your accepted paper is preserved.');$distributed=$old&&(bool)query('SELECT 1 FROM term_peer_assignments WHERE paper_id=?',[$old['id']])->fetchColumn();demand(!$distributed||in_array($old['teacher_status'],['revision','integrity_review'],true),'This revision is already allocated for peer review. Wait for professor feedback.');
  $new=$old===null||$old['status']==='submitted';$id=$new?bin2hex(random_bytes(16)):$old['id'];$rev=$new?(int)($old['revision']??0)+1:(int)$old['revision'];$version=(int)($old['version']??0)+1;$status=$submit?'submitted':'draft';$time=gmdate('c',$now);
  if($new)query('INSERT INTO term_papers (id,enrollment_id,week_index,task_kind,revision,document_json,word_count,status,originality,peer_consent,consent_version,version,updated_at,submitted_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$en['id'],$week,$task,$rev,json_encode($validated['document'],JSON_THROW_ON_ERROR),$validated['words'],$status,$submit?1:0,$submit?1:0,$submit?TERM_CONSENT_VERSION:0,$version,$time,$submit?$time:null]);
  else query("UPDATE term_papers SET document_json=?,word_count=?,status=?,originality=?,peer_consent=?,consent_version=?,teacher_status='pending',feedback=NULL,rubric_json=NULL,version=?,updated_at=?,submitted_at=?,reviewed_at=NULL WHERE id=?",[json_encode($validated['document'],JSON_THROW_ON_ERROR),$validated['words'],$status,$submit?1:0,$submit?1:0,$submit?TERM_CONSENT_VERSION:0,$version,$time,$submit?$time:null,$id]);
  if($submit||$validated['words']>0)term_touch($en['id'],$now);db()->commit();if($submit)term_route_submission($off,$en,$week,$task,$now);return term_public_paper(term_latest($en['id'],$week,$task));
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function term_rubric($raw):array{demand(is_array($raw),'Complete every rubric criterion.');$out=[];foreach(TERM_RUBRIC as $key){$v=$raw[$key]??null;demand(is_int($v)&&$v>=0&&$v<=4,'Score each rubric criterion from 0 to 4.');$out[$key]=$v;}return $out;}
function term_peer_route(string $paper):?array{return query('SELECT * FROM term_peer_routes WHERE paper_id=?',[$paper])->fetch()?:null;}
function term_peer_frozen(array $enrollment,int $week):bool{
 if(in_array($enrollment['status'],['completed','unenrolled_inactive'],true))return true;
 return (bool)query('SELECT 1 FROM assessment_attempts WHERE user_id=? AND assessment_key IN (?,?) LIMIT 1'.(db()->inTransaction()&&db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$enrollment['user_id'],term_assessment_key($enrollment['offering_id'],'w'.sprintf('%02d',$week+1)),term_assessment_key($enrollment['offering_id'],'f')])->fetchColumn()||(bool)query('SELECT 1 FROM term_certificates WHERE enrollment_id=?',[$enrollment['id']])->fetchColumn();
}
function term_record_route(array $paper,?string $batch,string $outcome,string $reason,int $now,?array $actor=null):void{
 demand(in_array($outcome,['assigned','professor_fallback'],true),'Choose a valid review route.');if(term_peer_route($paper['id']))return;
 query('INSERT INTO term_peer_routes (paper_id,batch_id,outcome,reason,decided_by,decided_at) VALUES (?,?,?,?,?,?)',[$paper['id'],$batch,$outcome,$reason,$actor['id']??null,gmdate('c',$now)]);
 if($actor)campus_audit($actor,'term_peer_route',$paper['id'],['outcome'=>$outcome,'batch'=>$batch,'reason'=>$reason]);else query("INSERT INTO campus_audit (actor_id,action,subject,detail_json,created_at) VALUES ('system','term_peer_route',?,?,?)",[$paper['id'],json_encode(['outcome'=>$outcome,'batch'=>$batch,'reason'=>$reason]),gmdate('c',$now)]);
}
function term_route_submission(array $offering,array $enrollment,int $week,string $task,int $now):void{term_allocate_batch($offering,$week,$task,$now);}

function term_allocate_batch(array $offering,int $week,string $task,int $now,bool $service=false):bool{
 demand($week>=0&&$week<10&&in_array($task,['opening','closing'],true),'Choose a module writing task.');$cutoff=$service?term_service_cutoff($now):$now;$own=!db()->inTransaction();if($own)db()->beginTransaction();
 try{
  term_lock_offering($offering['id']);$mysql=db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql';$enrollments=query('SELECT * FROM term_enrollments WHERE offering_id=? ORDER BY id'.($mysql?' FOR UPDATE':''),[$offering['id']])->fetchAll();$members=[];foreach($enrollments as $en)$members[$en['id']]=$en;
  $at=gmdate('c',$cutoff);$rows=query("SELECT p.* FROM term_papers p JOIN term_enrollments e ON e.id=p.enrollment_id WHERE e.offering_id=? AND p.week_index=? AND p.task_kind=? AND p.status='submitted' AND p.originality=1 AND p.peer_consent=1 AND p.consent_version=? AND p.teacher_status IN ('pending','accepted') AND p.submitted_at<=? AND NOT EXISTS(SELECT 1 FROM term_peer_routes r WHERE r.paper_id=p.id) AND NOT EXISTS(SELECT 1 FROM term_papers n WHERE n.enrollment_id=p.enrollment_id AND n.week_index=p.week_index AND n.task_kind=p.task_kind AND n.status='submitted' AND n.revision>p.revision) ORDER BY p.enrollment_id",[$offering['id'],$week,$task,TERM_CONSENT_VERSION,$at])->fetchAll();$eligible=[];foreach($rows as $paper){$en=$members[$paper['enrollment_id']]??null;if(!$en||$en['status']==='unenrolled_inactive')continue;if(term_peer_frozen($en,$week)){term_record_route($paper,null,'professor_fallback','Assessment duties are already frozen; this revised paper requires professor review only.',$now);continue;}if(in_array($en['status'],['enrolled','finished'],true))$eligible[]=$paper;}$rows=$eligible;$count=count($rows);if($count===0||($count===1&&!$service))return false;
  $rows=term_shuffle($rows);$id=bin2hex(random_bytes(16));query('INSERT INTO term_batches (id,offering_id,week_index,task_kind,cutoff_at,processed_at,papers_count,teacher_fallback) VALUES (?,?,?,?,?,?,?,?)',[$id,$offering['id'],$week,$task,$at,gmdate('c',$now),$count,$count===1?1:0]);
  foreach($rows as $i=>$author){if($count===1){term_record_route($author,$id,'professor_fallback','No eligible partner was available at the Thursday 08:00 Nairobi routing service. Await professor review.',$now);continue;}$reviewer=$rows[($i+1)%$count];if($author['enrollment_id']===$reviewer['enrollment_id'])throw new RuntimeException('Peer allocation cannot assign self-review.');query('INSERT INTO term_peer_assignments (id,batch_id,paper_id,reviewer_enrollment_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$id,$author['id'],$reviewer['enrollment_id']]);term_record_route($author,$id,'assigned','Randomly paired with another eligible submitter in this intake group and module task.',$now);}
  query("INSERT INTO campus_audit (actor_id,action,subject,detail_json,created_at) VALUES ('system',?,?,?,?)",['term_peer_allocation',$id,json_encode(['offering'=>$offering['id'],'module'=>$week,'task'=>$task,'papers'=>$count,'teacherFallback'=>$count===1,'service'=>$service]),gmdate('c',$now)]);return true;
 }catch(Throwable $e){if($own&&db()->inTransaction())db()->rollBack();throw $e;}finally{if($own&&db()->inTransaction())db()->commit();}
}

function terms_run_due(int $now,int $max=100,bool $cron=false):array{
 if(!terms_ready())return ['installed'=>false];$done=0;$expired=0;$offset=(int)(query('SELECT scan_offset FROM term_scheduler WHERE id=1')->fetchColumn()?:0);
 $offers=query("SELECT o.* FROM term_offerings o WHERE EXISTS(SELECT 1 FROM term_enrollments e WHERE e.offering_id=o.id AND e.status IN ('enrolled','finished')) ORDER BY o.start_date,o.id LIMIT 50 OFFSET ".$offset)->fetchAll();
 foreach($offers as $off){for($w=0;$w<10;$w++){if($done>=$max)break;foreach(['opening','closing'] as $task){if($done>=$max)break;if(term_allocate_batch($off,$w,$task,$now,true))$done++;}}
  $own=!db()->inTransaction();if($own)db()->beginTransaction();try{term_lock_offering($off['id']);$idle=query("SELECT id FROM term_enrollments WHERE offering_id=? AND status IN ('enrolled','finished') AND last_activity_at IS NULL AND enrolled_at<=?",[$off['id'],gmdate('c',$now-84*86400)])->fetchAll(PDO::FETCH_COLUMN);foreach($idle as $eid){term_lock_enrollment($eid);$changed=query("UPDATE term_enrollments SET status='unenrolled_inactive',ended_at=? WHERE id=? AND last_activity_at IS NULL AND status IN ('enrolled','finished')",[gmdate('c',$now),$eid])->rowCount();if($changed!==1)continue;query("INSERT INTO campus_audit (actor_id,action,subject,detail_json,created_at) VALUES ('system','term_inactive_expiry',?,?,?)",[$eid,json_encode(['offering'=>$off['id'],'afterDays'=>84,'basis'=>'individual enrollment with no recorded study work']),gmdate('c',$now)]);$expired++;}if($own)db()->commit();}catch(Throwable $e){if($own&&db()->inTransaction())db()->rollBack();throw $e;}
 }
 $sql=db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?'INSERT INTO term_scheduler (id,last_run_at,batches_processed,inactive_unenrolled) VALUES (1,?,?,?) ON DUPLICATE KEY UPDATE last_run_at=VALUES(last_run_at),batches_processed=batches_processed+VALUES(batches_processed),inactive_unenrolled=inactive_unenrolled+VALUES(inactive_unenrolled)':'INSERT INTO term_scheduler (id,last_run_at,batches_processed,inactive_unenrolled) VALUES (1,?,?,?) ON CONFLICT(id) DO UPDATE SET last_run_at=excluded.last_run_at,batches_processed=term_scheduler.batches_processed+excluded.batches_processed,inactive_unenrolled=term_scheduler.inactive_unenrolled+excluded.inactive_unenrolled';query($sql,[gmdate('c',$now),$done,$expired]);query('UPDATE term_scheduler SET scan_offset=? WHERE id=1',[count($offers)<50?0:$offset+50]);if($cron)query('UPDATE term_scheduler SET last_cron_at=? WHERE id=1',[gmdate('c',$now)]);return ['installed'=>true,'batches'=>$done,'inactiveUnenrolled'=>$expired,'activeTermsEnded'=>0];
}

function term_peer_payload(array $u,string $assignment):array{
 $r=query('SELECT p.*,a.id AS assignment_id,a.reviewer_enrollment_id,a.rubric_json AS peer_rubric,a.feedback AS peer_feedback,a.score AS peer_score,a.submitted_at AS peer_submitted,a.version AS peer_version,b.offering_id FROM term_peer_assignments a JOIN term_batches b ON b.id=a.batch_id JOIN term_papers p ON p.id=a.paper_id WHERE a.id=?',[$assignment])->fetch();demand((bool)$r,'Peer review not found.');$en=term_enrollment($u,$r['offering_id']);demand($r['reviewer_enrollment_id']===$en['id'],'This peer review belongs to another learner.');demand($r['enrollment_id']!==$en['id'],'You cannot review your own paper.');
 $course=term_course(term_offering($r['offering_id'])['course_id']);$alias='Learner '.strtoupper(substr(hash_hmac('sha256',$r['enrollment_id'].':'.$r['offering_id'],settings()['app_key']),0,6));
 return ['id'=>$r['assignment_id'],'version'=>(int)$r['peer_version'],'courseTitle'=>$course['title'],'week'=>(int)$r['week_index'],'task'=>$r['task_kind'],'authorAlias'=>$alias,'document'=>json_decode($r['document_json'],true),'prompt'=>$course['weeks'][(int)$r['week_index']][$r['task_kind']],'review'=>['rubric'=>$r['peer_rubric']?json_decode($r['peer_rubric'],true):null,'feedback'=>$r['peer_feedback'],'score'=>$r['peer_score']===null?null:(int)$r['peer_score'],'submittedAt'=>$r['peer_submitted']]];
}
function term_save_peer(array $u,array $body,int $now):void{
