function term_quiz_paper(string $key,bool $shuffle=false):array{
 demand((bool)preg_match('/^t-([a-f0-9]{8})-(w(?:0[1-9]|10)|m|f)$/D',$key,$m),'Choose a valid standard-course assessment.');$off=term_offering($m[1]);$course=term_course($off['course_id']);$part=$m[2];$week=str_starts_with($part,'w')?(int)substr($part,1)-1:null;
 if($week!==null){$questions=$course['weeks'][$week]['questions'];$title=$course['weeks'][$week]['title'].' — module checkpoint';$kind='term_module';$pass=100;foreach($questions as &$q)$q['section']='Module '.($week+1).' · True or false';unset($q);if($shuffle)shuffle($questions);}
 elseif($part==='m'){$questions=[];foreach(array_slice($course['weeks'],0,6) as $wi=>$w){$pool=$shuffle?term_shuffle($w['questions']):$w['questions'];$questions=array_merge($questions,array_slice($pool,0,$wi<4?3:4));}if($shuffle)$questions=term_shuffle($questions);$title='After Module 6 · Mid-course assessment';$kind='term_mid';$pass=100;foreach($questions as &$q)$q['section']='Mid-course · True or false';unset($q);}
 else{$a=$course['final']['a'];$b=$course['final']['b'];foreach($a as &$q){$q['section']='Section A · Single answer';if($shuffle){$old=$q['answers'];$order=term_shuffle(range(0,count($old)-1));$q['answers']=array_map(fn($i)=>$old[$i],$order);$q['correct']=array_search($q['correct'],$order,true);}}unset($q);foreach($b as &$q){$q['section']='Section B · Independent statements';if($shuffle)$q['statements']=term_shuffle($q['statements']);}unset($q);if($shuffle){$a=term_shuffle($a);$b=term_shuffle($b);}$questions=array_merge($a,$b);$title='Final course examination';$kind='term_final';$pass=85;}
 return ['key'=>$key,'revision'=>1,'title'=>$course['title'].' — '.$title,'kind'=>$kind,'module'=>$week,'pass_percent'=>$pass,'seconds_per_question'=>120,'questions'=>$questions,'term'=>['offering'=>$off['id'],'course'=>$off['course_id'],'courseTitle'=>$course['title'],'part'=>$part,'week'=>$week],'reference_sources'=>$course['sources']];
}
function term_shuffle(array $items):array{for($i=count($items)-1;$i>0;$i--){$j=random_int(0,$i);[$items[$i],$items[$j]]=[$items[$j],$items[$i]];}return $items;}
function term_quiz_eligible(array $paper,string $userId,int $now):bool{
 if(!terms_ready())return false;$t=$paper['term'];$off=term_offering($t['offering']);$en=query('SELECT * FROM term_enrollments WHERE offering_id=? AND user_id=?',[$off['id'],$userId])->fetch();if(!$en||$en['status']==='unenrolled_inactive')return false;$part=$t['part'];
 if($t['week']!==null)return term_previous_passed($en,$t['week'])&&term_week_complete_writing($en,$t['week']);
 $count=$part==='m'?6:10;for($i=0;$i<$count;$i++)if(!term_passed($userId,$off['id'],'w'.sprintf('%02d',$i+1))||!term_week_complete_writing($en,$i))return false;
