}

function term_credit(array $paper,array $result,string $userId,string $attemptId,int $now):void{
 $t=$paper['term'];$own=!db()->inTransaction();if($own)db()->beginTransaction();
 try{
  $mysql=db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql';if(!$mysql)query('UPDATE term_enrollments SET id=id WHERE user_id=? AND offering_id=?',[$userId,$t['offering']]);
  $en=query('SELECT * FROM term_enrollments WHERE user_id=? AND offering_id=?'.($mysql?' FOR UPDATE':''),[$userId,$t['offering']])->fetch();if(!$en)throw new RuntimeException('Assessment enrollment is missing.');term_touch($en['id'],$now);
  if(!$result['passed']||$paper['kind']!=='term_final')return;for($i=0;$i<10;$i++)if(!term_week_complete_writing($en,$i)||!term_passed($userId,$t['offering'],'w'.sprintf('%02d',$i+1)))return;if(!term_passed($userId,$t['offering'],'m'))return;
  if(query('SELECT id FROM term_certificates WHERE enrollment_id=?',[$en['id']])->fetchColumn())return;
  $u=query('SELECT id,email,display_name,verified_at FROM users WHERE id=?',[$userId])->fetch();$student=student_record($u);$id=bin2hex(random_bytes(16));$number='SMB-'.gmdate('Y',$now).'-'.strtoupper($t['offering']).'-'.sprintf('%06d',(int)$student['student_sequence']);$name=$paper['candidate_name']??($student['full_name']?:$u['display_name']);query('INSERT INTO term_certificates (id,enrollment_id,user_id,certificate_number,student_number,student_name,course_title,attempt_id,score,maximum,signatories_json,issued_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$en['id'],$userId,$number,student_number((int)$student['student_sequence']),$name,$t['courseTitle'],$attemptId,$result['score'],$result['maximum'],json_encode(certificate_signatories()),gmdate('c',$now)]);query("UPDATE term_enrollments SET status='completed',ended_at=? WHERE id=?",[gmdate('c',$now),$en['id']]);
 }catch(Throwable $e){if($own&&db()->inTransaction())db()->rollBack();throw $e;}finally{if($own&&db()->inTransaction())db()->commit();}
}
// A professor can request a revision while a final attempt is active. Preserve its
// earned score and issue only when the outstanding requirements are later resolved.
function term_reconcile_certificate(string $userId,string $offering,int $now):void{
 if(query('SELECT 1 FROM term_certificates c JOIN term_enrollments e ON e.id=c.enrollment_id WHERE e.user_id=? AND e.offering_id=?',[$userId,$offering])->fetchColumn())return;
 $row=query('SELECT id,paper_json,result_json,score,maximum FROM assessment_attempts WHERE user_id=? AND assessment_key=? AND passed=1 AND submitted_at IS NOT NULL ORDER BY submitted_at,id LIMIT 1',[$userId,term_assessment_key($offering,'f')])->fetch();if(!$row)return;
 $paper=json_decode($row['paper_json'],true,128,JSON_THROW_ON_ERROR);$result=json_decode($row['result_json'],true,128,JSON_THROW_ON_ERROR);
 if(($paper['kind']??null)!=='term_final'||($paper['term']['offering']??null)!==$offering||($paper['term']['part']??null)!=='f'||($result['passed']??null)!==true||(int)$row['maximum']!==55||($result['maximum']??null)!==55||($result['score']??null)!==(int)$row['score']||(int)$row['score']<47||(int)$row['score']>55)return;
 term_credit($paper,$result,$userId,$row['id'],$now);
}

// The public catalogue deliberately contains outcomes and calendar only. Lesson text,
// papers and answer banks are never returned by this endpoint to an unenrolled user.
