 return ['id'=>$c['id'],'code'=>$c['code'],'title'=>$c['title'],'summary'=>$c['summary'],'outcomes'=>$c['outcomes'],'durationWeeks'=>12,'recommendedPlanWeeks'=>12,'selfPaced'=>true,'capacity'=>TERM_CAPACITY,'prerequisite'=>'College Success','edition'=>$c['edition'],'weeks'=>array_map(fn($w)=>['title'=>$w['title'],'goal'=>$w['goal'],'outcomes'=>$w['outcomes'],'studyHours'=>$w['studyHours']],$c['weeks'])];
