// Percentages describe earned teaching-week mastery, not elapsed time, page views
// or video clicks. A final pass and issued completion record remain separate.
function term_progress_summary(array $statuses,bool $midPassed,bool $finalPassed,bool $awarded=false):array{
 $weeks=[];foreach($statuses as $row){$week=$row['week']??null;if(!is_int($week)||$week<0||$week>=10)continue;$weeks[$week]=$row;}
 $next=11;for($i=0;$i<10;$i++)if(($weeks[$i]['passed']??false)!==true){$next=$i;break;}if($next>=6&&!$midPassed)$next=5;$passed=0;$writing=0;foreach($weeks as $row){if(($row['passed']??false)===true)$passed++;foreach(['opening','closing'] as $task)if(($row[$task]??null)==='accepted')$writing++;}
 return ['weeklyPassed'=>$passed,'nextModule'=>$next,'teachingWeeks'=>10,'masteryPercent'=>$passed*10,'acceptedWriting'=>$writing,'requiredWriting'=>20,'midPassed'=>$midPassed,'finalPassed'=>$finalPassed,'completed'=>$awarded];
}
function term_progress_for_enrollment(array $en,string $userId):array{
 $statuses=[];for($i=0;$i<10;$i++)$statuses[$i]=['week'=>$i,'passed'=>false,'opening'=>null,'closing'=>null];
 $prefix='t-'.$en['offering_id'].'-';$passed=query('SELECT DISTINCT assessment_key FROM assessment_attempts WHERE user_id=? AND assessment_key LIKE ? AND passed=1 AND submitted_at IS NOT NULL',[$userId,$prefix.'%'])->fetchAll(PDO::FETCH_COLUMN);$mid=false;$final=false;
 foreach($passed as $key){$part=substr($key,strlen($prefix));if(preg_match('/^w(0[1-9]|10)$/D',$part,$m))$statuses[(int)$m[1]-1]['passed']=true;elseif($part==='m')$mid=true;elseif($part==='f')$final=true;}
 $papers=query("SELECT p.week_index,p.task_kind,p.teacher_status FROM term_papers p WHERE p.enrollment_id=? AND p.status='submitted' AND NOT EXISTS(SELECT 1 FROM term_papers n WHERE n.enrollment_id=p.enrollment_id AND n.week_index=p.week_index AND n.task_kind=p.task_kind AND n.status='submitted' AND n.revision>p.revision)",[$en['id']])->fetchAll();
 foreach($papers as $paper){$week=(int)$paper['week_index'];if(isset($statuses[$week])&&in_array($paper['task_kind'],['opening','closing'],true))$statuses[$week][$paper['task_kind']]=$paper['teacher_status'];}
 $awarded=(bool)query('SELECT 1 FROM term_certificates WHERE enrollment_id=?',[$en['id']])->fetchColumn();return term_progress_summary($statuses,$mid,$final,$awarded);
}
