 $mine=$installed&&$u?query('SELECT e.id,e.offering_id,e.status,e.enrolled_at,o.course_id,o.start_date FROM term_enrollments e JOIN term_offerings o ON o.id=e.offering_id WHERE e.user_id=? ORDER BY o.start_date DESC,e.enrolled_at DESC',[$u['id']])->fetchAll():[];
