 $statuses=[];for($i=0;$i<10;$i++){$opening=$en?term_latest_submitted($en['id'],$i,'opening'):null;$closing=$en?term_latest_submitted($en['id'],$i,'closing'):null;$statuses[]=['week'=>$i,'passed'=>$en?term_passed($u['id'],$id,'w'.sprintf('%02d',$i+1)):false,'opening'=>$opening['teacher_status']??null,'closing'=>$closing['teacher_status']??null];}
