 if($week<10){
  $out['deadline']=null;
  if($en){foreach(['opening','closing'] as $task){$out['papers'][$task]=term_public_paper(term_latest($en['id'],$week,$task));$out['submittedPapers'][$task]=term_public_paper(term_latest_submitted($en['id'],$week,$task));}
