   $practice=query('SELECT notes,version,updated_at FROM term_practice WHERE enrollment_id=? AND week_index=?',[$en['id'],$week])->fetch();$out['practice']=$practice?['notes'=>$practice['notes'],'version'=>(int)$practice['version'],'updatedAt'=>$practice['updated_at']]:['notes'=>'','version'=>0,'updatedAt'=>null];
