 }else{$out['content']=['title'=>$week===10?'Review and retrieval practice':'Final examination','goal'=>$week===10?'Retrieve, explain and revisit the ten topics. Use feedback to correct weak understanding.':'Demonstrate your understanding in the final course examination.','reviewTopics'=>array_map(fn($w)=>['title'=>$w['title'],'outcomes'=>$w['outcomes']],$course['weeks'])];}
 $params=[$id,$week];$where='offering_id=? AND week_index=?';if(!$teacher){$where.=" AND (status='approved' OR user_id=?)";$params[]=$u['id'];}
 $rows=query('SELECT id,user_id,body,status,created_at FROM term_discussions WHERE '.$where.' ORDER BY created_at DESC,id DESC LIMIT 50',$params)->fetchAll();foreach(array_reverse($rows) as $r){$author=query('SELECT id,email,display_name,verified_at FROM users WHERE id=?',[$r['user_id']])->fetch();$out['discussion'][]=['id'=>$r['id'],'name'=>campus_name($author),'body'=>$r['body'],'status'=>$r['status'],'createdAt'=>$r['created_at'],'mine'=>$r['user_id']===$u['id']];}
