function term_certificate(string $userId,string $offering):?array{$r=query('SELECT c.* FROM term_certificates c JOIN term_enrollments e ON e.id=c.enrollment_id WHERE c.user_id=? AND e.offering_id=?',[$userId,$offering])->fetch();return $r?certificate_public($r):null;}
function term_save_practice(array $u,array $b,int $now):void{
 $off=term_offering((string)($b['offering']??''));$en=term_enrollment($u,$off['id']);$w=$b['week']??null;demand(is_int($w)&&$w>=0&&$w<10,'Choose a teaching week.');demand($en['status']!=='unenrolled_inactive','This practice is not available.');$notes=campus_text($b['notes']??null,12000);demand(is_int($b['version']??null),'Refresh the practice notes.');
 db()->beginTransaction();try{term_lock_enrollment($en['id']);demand(query('SELECT status FROM term_enrollments WHERE id=?',[$en['id']])->fetchColumn()!=='unenrolled_inactive','This inactive enrollment has ended. Enroll again to continue new work.');$old=query('SELECT version FROM term_practice WHERE enrollment_id=? AND week_index=?',[$en['id'],$w])->fetchColumn();if((int)$old!==$b['version']){db()->rollBack();reply(['error'=>'These notes changed on another device. Copy your draft, refresh and compare before saving.','conflict'=>true],409);}if($old===false)query('INSERT INTO term_practice (enrollment_id,week_index,notes,updated_at) VALUES (?,?,?,?)',[$en['id'],$w,$notes,gmdate('c',$now)]);else query('UPDATE term_practice SET notes=?,version=version+1,updated_at=? WHERE enrollment_id=? AND week_index=?',[$notes,gmdate('c',$now),$en['id'],$w]);term_touch($en['id'],$now);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function term_discuss(array $u,array $b,int $now):void{
 [$off,$en,$teacher]=term_class_access($u,(string)($b['offering']??''));$week=$b['week']??null;demand(is_int($week)&&$week>=0&&$week<12,'Choose a course week.');demand($teacher||($en&&in_array($en['status'],['enrolled','finished','completed'],true)),'This discussion is not open.');$controls=campus_controls($u['id']);demand($teacher||(!$controls['muted']&&!$controls['read_only']&&!$controls['suspended']),'Posting is restricted for this account.');demand($teacher||!(bool)$off['discussion_locked'],'The professor has paused this class discussion.');$text=campus_text($b['text']??null,2500);$request=$b['requestId']??'';demand(is_string($request)&&(bool)preg_match('/^[a-f0-9]{32}$/D',$request),'Refresh the discussion before posting.');$old=query('SELECT offering_id,week_index,body FROM term_discussions WHERE user_id=? AND request_id=?',[$u['id'],$request])->fetch();if($old){demand($old['offering_id']===$off['id']&&(int)$old['week_index']===$week&&$old['body']===$text,'This request was already used.');return;}
 limited('term-discussion',10,60,$u['id']);demand((int)query('SELECT COUNT(*) FROM term_discussions WHERE offering_id=?',[$off['id']])->fetchColumn()<5000,'This class discussion has reached its storage limit. Contact the professor.');query('INSERT INTO term_discussions (id,offering_id,week_index,user_id,body,status,request_id,created_at) VALUES (?,?,?,?,?,?,?,?)',[bin2hex(random_bytes(16)),$off['id'],$week,$u['id'],$text,$teacher?'approved':'pending',$request,gmdate('c',$now)]);if($en)term_touch($en['id'],$now);
}
function term_moderate(array $u,array $b):void{
 $r=query('SELECT * FROM term_discussions WHERE id=?',[(string)($b['message']??'')])->fetch();demand($r&&term_professor($u,$r['offering_id']),'Only this class professor can moderate the discussion.');$status=$b['status']??'';demand(in_array($status,['approved','hidden'],true),'Choose an approval or removal.');$reason=campus_text($b['reason']??null,1000);db()->beginTransaction();try{query('UPDATE term_discussions SET status=? WHERE id=?',[$status,$r['id']]);campus_audit($u,'term_discussion_moderate',$r['id'],['before'=>$r['status'],'after'=>$status,'reason'=>$reason]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function term_room_lock(array $u,array $b):void{
 $off=term_offering((string)($b['offering']??''));demand(term_professor($u,$off['id']),'Only this class professor can pause the discussion.');demand(is_bool($b['locked']??null)&&is_int($b['version']??null),'Refresh the class settings.');$reason=campus_text($b['reason']??null,1000);db()->beginTransaction();try{$n=query('UPDATE term_offerings SET discussion_locked=?,version=version+1 WHERE id=? AND version=?',[(int)$b['locked'],$off['id'],$b['version']])->rowCount();demand($n===1,'The class settings changed. Refresh first.');campus_audit($u,'term_room_lock',$off['id'],['before'=>(bool)$off['discussion_locked'],'after'=>$b['locked'],'reason'=>$reason]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function term_office(array $u,?string $offering=null):array{
 $staff=campus_staff($u);$offers=$staff?query('SELECT * FROM term_offerings ORDER BY start_date DESC LIMIT 100')->fetchAll():query('SELECT o.* FROM term_offerings o JOIN term_professors p ON p.offering_id=o.id WHERE p.user_id=? ORDER BY o.start_date DESC LIMIT 100',[$u['id']])->fetchAll();
 if(!$staff&&!$offers)reply(['error'=>'Class professor access required.'],403);foreach($offers as &$o)$o['title']=term_course($o['course_id'])['title'];unset($o);$out=['offerings'=>$offers,'scheduler'=>$staff?(query('SELECT * FROM term_scheduler WHERE id=1')->fetch()?:null):null,'queue'=>[],'students'=>[],'discussions'=>[],'audit'=>[]];if(!$offering)return $out;
 $off=term_offering($offering);demand(term_professor($u,$offering),'Only this class professor can open its office.');$out['offering']=$off;$out['course']=term_syllabus(term_course($off['course_id']));
 $out['queue']=query("SELECT p.id,p.week_index,p.task_kind,p.revision,p.word_count,p.teacher_status,p.submitted_at,e.user_id,COALESCE(s.full_name,u.display_name) AS name FROM term_papers p JOIN term_enrollments e ON e.id=p.enrollment_id JOIN users u ON u.id=e.user_id LEFT JOIN course_students s ON s.user_id=e.user_id WHERE e.offering_id=? AND p.status='submitted' AND NOT EXISTS(SELECT 1 FROM term_papers n WHERE n.enrollment_id=p.enrollment_id AND n.week_index=p.week_index AND n.task_kind=p.task_kind AND n.status='submitted' AND n.revision>p.revision) ORDER BY p.submitted_at DESC LIMIT 120",[$offering])->fetchAll();
 $out['students']=query('SELECT e.*,COALESCE(s.full_name,u.display_name) AS name,s.student_sequence FROM term_enrollments e JOIN users u ON u.id=e.user_id LEFT JOIN course_students s ON s.user_id=e.user_id WHERE e.offering_id=? ORDER BY e.enrolled_at',[$offering])->fetchAll();foreach($out['students'] as &$st){$st['grades']=term_gradebook($st['user_id'],$offering);$st['extensions']=query('SELECT week_index,until_at,reason FROM term_extensions WHERE enrollment_id=? ORDER BY week_index',[$st['id']])->fetchAll();}unset($st);
 $out['discussions']=query("SELECT d.*,COALESCE(s.full_name,u.display_name) AS name FROM term_discussions d JOIN users u ON u.id=d.user_id LEFT JOIN course_students s ON s.user_id=d.user_id WHERE d.offering_id=? AND d.status='pending' ORDER BY d.created_at LIMIT 50",[$offering])->fetchAll();
 $subjects=[$offering];foreach($out['students'] as $st)$subjects[]=$st['id'];foreach(query('SELECT p.id FROM term_papers p JOIN term_enrollments e ON e.id=p.enrollment_id WHERE e.offering_id=?',[$offering])->fetchAll(PDO::FETCH_COLUMN) as $s)$subjects[]=$s;foreach(query('SELECT a.id FROM term_peer_assignments a JOIN term_batches b ON b.id=a.batch_id WHERE b.offering_id=?',[$offering])->fetchAll(PDO::FETCH_COLUMN) as $s)$subjects[]=$s;foreach(query('SELECT id FROM term_batches WHERE offering_id=?',[$offering])->fetchAll(PDO::FETCH_COLUMN) as $s)$subjects[]=$s;foreach(query('SELECT id FROM term_discussions WHERE offering_id=?',[$offering])->fetchAll(PDO::FETCH_COLUMN) as $s)$subjects[]=$s;
 $marks=implode(',',array_fill(0,count($subjects),'?'));$out['audit']=query('SELECT a.id,a.action,a.subject,a.detail_json,a.created_at,COALESCE(u.display_name,\'School scheduler\') AS actor FROM campus_audit a LEFT JOIN users u ON u.id=a.actor_id WHERE a.subject IN ('.$marks.') ORDER BY a.id DESC LIMIT 100',$subjects)->fetchAll();$out['professors']=query('SELECT p.user_id,u.display_name,u.email,p.assigned_at FROM term_professors p JOIN users u ON u.id=p.user_id WHERE p.offering_id=?',[$offering])->fetchAll();return $out;
}
function term_teacher_paper(array $u,string $id):array{
 $p=query('SELECT p.*,e.user_id,e.offering_id FROM term_papers p JOIN term_enrollments e ON e.id=p.enrollment_id WHERE p.id=? AND p.status=\'submitted\'',[$id])->fetch();demand($p&&term_professor($u,$p['offering_id']),'This submitted paper is unavailable.');$author=query('SELECT id,email,display_name,verified_at FROM users WHERE id=?',[$p['user_id']])->fetch();$out=['paper'=>term_public_paper($p),'name'=>campus_name($author),'studentNumber'=>student_public(student_record($author))['number'],'ownPaper'=>$u['id']===$p['user_id'],'offering'=>$p['offering_id'],'prompt'=>term_course(term_offering($p['offering_id'])['course_id'])['weeks'][(int)$p['week_index']][$p['task_kind']],'peers'=>[]];foreach(query('SELECT * FROM term_peer_assignments WHERE paper_id=?',[$id])->fetchAll() as $a){$v=term_effective_peer($a);$v['history']=query('SELECT revision,rubric_json,reason,created_at FROM term_peer_adjustments WHERE assignment_id=? ORDER BY revision',[$a['id']])->fetchAll();$out['peers'][]=$v;}return $out;
}
function term_assign_professor(array $u,array $b):void{
 demand(campus_staff($u),'Only the school super administrator can assign a class professor.');$off=term_offering((string)($b['offering']??''));$email=strtolower(trim((string)($b['email']??'')));$target=query('SELECT id,verified_at FROM users WHERE email=?',[$email])->fetch();demand($target&&$target['verified_at']!==null,'Choose an existing verified school account.');demand(is_bool($b['enabled']??null),'Choose whether this professor role is enabled.');$reason=campus_text($b['reason']??null,1000);db()->beginTransaction();try{query('DELETE FROM term_professors WHERE offering_id=? AND user_id=?',[$off['id'],$target['id']]);if($b['enabled'])query('INSERT INTO term_professors (offering_id,user_id,assigned_at) VALUES (?,?,?)',[$off['id'],$target['id'],gmdate('c')]);campus_audit($u,'term_professor_role',$off['id'],['userId'=>$target['id'],'enabled'=>$b['enabled'],'reason'=>$reason]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function term_gradebook(string $userId,?string $offering=null):array{
 if(!terms_ready())return [];$p=[$userId];$where='e.user_id=?';if($offering){$where.=' AND e.offering_id=?';$p[]=$offering;}$ens=query('SELECT e.*,o.course_id,o.start_date FROM term_enrollments e JOIN term_offerings o ON o.id=e.offering_id WHERE '.$where.' ORDER BY o.start_date DESC',$p)->fetchAll();$out=[];
 foreach($ens as $en){term_reconcile_certificate($userId,$en['offering_id'],time());$en['status']=query('SELECT status FROM term_enrollments WHERE id=?',[$en['id']])->fetchColumn()?:$en['status'];$key='t-'.$en['offering_id'].'-%';$attempts=query('SELECT id,assessment_key,score,maximum,passed,submitted_at FROM assessment_attempts WHERE user_id=? AND assessment_key LIKE ? AND submitted_at IS NOT NULL ORDER BY submitted_at DESC LIMIT 100',[$userId,$key])->fetchAll();$out[]=['offering'=>$en['offering_id'],'title'=>term_course($en['course_id'])['title'],'status'=>$en['status'],'startDate'=>$en['start_date'],'attempts'=>$attempts,'papers'=>query('SELECT p.week_index,p.task_kind,p.teacher_status,p.rubric_json,p.feedback,p.reviewed_at FROM term_papers p WHERE p.enrollment_id=? AND p.status=\'submitted\' AND NOT EXISTS(SELECT 1 FROM term_papers n WHERE n.enrollment_id=p.enrollment_id AND n.week_index=p.week_index AND n.task_kind=p.task_kind AND n.status=\'submitted\' AND n.revision>p.revision) ORDER BY p.week_index,p.task_kind',[$en['id']])->fetchAll(),'certificate'=>term_certificate($userId,$en['offering_id'])];}return $out;
}
function term_snapshot_legacy(int $now):void{
 foreach(query('SELECT user_id,state_json FROM learning_accounts')->fetchAll() as $r){$s=json_decode($r['state_json'],true);$actual=!empty($s['completed'])||!empty($s['modulePasses'])||!empty($s['unitPasses']);if(!$actual)$actual=(bool)query('SELECT 1 FROM assessment_attempts WHERE user_id=? AND assessment_key NOT LIKE \'college-%\' AND assessment_key NOT LIKE \'t-%\' LIMIT 1',[$r['user_id']])->fetchColumn();if($actual)term_add_legacy($r['user_id'],'investing',$now);}
 foreach(query('SELECT user_id,state_json FROM speaking_accounts')->fetchAll() as $r){$s=json_decode($r['state_json'],true);$actual=false;foreach($s['modules']??[] as $m)if(!empty($m['passed'])||!empty($m['notes'])||!empty($m['bestScore'])){$actual=true;break;}if(!$actual)$actual=(bool)query('SELECT 1 FROM speaking_quiz_results WHERE user_id=? LIMIT 1',[$r['user_id']])->fetchColumn();if($actual)term_add_legacy($r['user_id'],'speaking',$now);}
 foreach(query("SELECT DISTINCT user_id,course_id FROM academic_submissions WHERE course_id IN ('investing','speaking')")->fetchAll() as $r)term_add_legacy($r['user_id'],$r['course_id'],$now);
}
function term_add_legacy(string $userId,string $course,int $now):void{if(!query('SELECT 1 FROM term_legacy_access WHERE user_id=? AND course_id=?',[$userId,$course])->fetchColumn())query('INSERT INTO term_legacy_access (user_id,course_id,recorded_at) VALUES (?,?,?)',[$userId,$course,gmdate('c',$now)]);}
function term_legacy_allowed(?array $u,string $course):bool{return !terms_ready()||($u&&(campus_staff($u)||(bool)query('SELECT 1 FROM term_legacy_access WHERE user_id=? AND course_id=?',[$u['id'],$course])->fetchColumn()));}
function term_curriculum_preview(array $u,string $course,int $week):array{
 demand(campus_staff($u),'School administrator access required for curriculum preview.');demand($week>=0&&$week<12,'Choose a course week.');$c=term_course($course);$content=$week<10?term_public_week($c['weeks'][$week]):['title'=>$week===10?'Review and retrieval practice':'Final examination','goal'=>'Review the course outcomes and assessment structure. This preview cannot award credit.','reviewTopics'=>array_map(fn($w)=>['title'=>$w['title'],'outcomes'=>$w['outcomes']],$c['weeks'])];
 return ['offering'=>['id'=>'preview/'.$course,'start_date'=>'Curriculum preview'],'enrollment'=>null,'professor'=>true,'preview'=>true,'clock'=>null,'course'=>term_syllabus($c),'week'=>$week,'statuses'=>array_fill(0,10,['passed'=>false]),'content'=>$content,'sources'=>$c['sources'],'papers'=>null,'peerReviews'=>[],'discussion'=>[],'practice'=>null,'locked'=>null,'certificate'=>null];
}
